async function seedDatabase() {
    try {
        await mongoose.connect(MONGO_URI);
        console.log('✅ Connected to MongoDB');
        // Check if data already exists
        const count = await Product.countDocuments();
        if (count > 0) {
            console.log(`⚠️  Database already has ${count} products. Skipping seed.`);
            console.log('💡 To reseed, delete the collection first: db.products.deleteMany({})');
            await mongoose.connection.close();
            process.exit(0);
        }
        // Insert all products
        const result = await Product.insertMany(SEED_PRODUCTS);
        console.log(`✅ Successfully seeded ${result.length} products to MongoDB`);
        console.log('📦 All 37 products are now in the database');
        await mongoose.connection.close();
        process.exit(0);
    }
    catch (error) {
        console.error('❌ Seed error:', error);
        process.exit(1);
    }
}
seedDatabase();
